fields.InputDefinition:
{
  "goal": "In the Predictive Studio app (open it via the application switcher dropdown next to the logo, scroll if needed), on the 'Predictions' door, open one prediction card by clicking its 'Open' button. Pages can take 10-30s to load — wait, don't navigate away. Success is the prediction WORKSPACE rendering: a trust banner with a star/dot rating and a plain-language verdict, plus either a ranked 'at-risk' call list (Member + Likelihood %) OR a trust-locked action bar showing a lock message when the prediction isn't reliable enough to act on. If the catalog has no openable cards (only the capability intro or 'Improve this' blocked cards), confirming that intro/blocked state renders is also a pass.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Opening a prediction shows a workspace with a trust banner and verdict, OR the catalog shows only blocked/intro state (no openable cards)",
    "When a workspace opens, either the ranked at-risk list renders or the action bar shows a trust-lock message — the trust verdict visibly gates the actions",
    "No error messages, blank screens, or crash pages"
  ]
}
